class Solution:
    def countTriplets(self, arr: List[int]) -> int:
        n = len(arr)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] ^ arr[i]
        count = 0
        for i in range(n):
            for k in range(i + 1, n):
                if prefix[i] == prefix[k + 1]:
                    count += k - i
        return count

class Solution:
    def minTime(self, n: int, edges: List[List[int]], hasApple: List[bool]) -> int:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        def dfs(node, parent):
            total = 0
            for child in graph[node]:
                if child == parent:
                    continue
                child_cost = dfs(child, node)
                if child_cost > 0 or hasApple[child]:
                    total += child_cost + 2
            return total
        return dfs(0, -1)

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(pizza), len(pizza[0])
        # suffix sum of apples
        apples = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m-1, -1, -1):
            for j in range(n-1, -1, -1):
                apples[i][j] = (1 if pizza[i][j]=='A' else 0) + apples[i+1][j] + apples[i][j+1] - apples[i+1][j+1]
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(i, j, cuts):
            if apples[i][j] == 0:
                return 0
            if cuts == 0:
                return 1
            res = 0
            for r in range(i+1, m):
                if apples[i][j] - apples[r][j] > 0:
                    res += dp(r, j, cuts-1)
            for c in range(j+1, n):
                if apples[i][j] - apples[i][c] > 0:
                    res += dp(i, c, cuts-1)
            return res % MOD
        return dp(0, 0, k-1)

