class Solution:
    def numPoints(self, darts: List[List[int]], r: int) -> int:
        import math
        n = len(darts)
        ans = 1
        for i in range(n):
            for j in range(i+1, n):
                dx = darts[j][0] - darts[i][0]
                dy = darts[j][1] - darts[i][1]
                d = math.sqrt(dx*dx + dy*dy)
                if d > 2*r:
                    continue
                h = math.sqrt(r*r - (d/2)**2)
                mx, my = (darts[i][0]+darts[j][0])/2, (darts[i][1]+darts[j][1])/2
                for cx, cy in [(mx + h*dy/d, my - h*dx/d), (mx - h*dy/d, my + h*dx/d)]:
                    cnt = sum(1 for k in range(n) if (darts[k][0]-cx)**2 + (darts[k][1]-cy)**2 <= r*r + 1e-6)
                    ans = max(ans, cnt)
        return ans

