class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        median = arr[(len(arr) - 1) // 2]
        left, right = 0, len(arr) - 1
        res = []
        while len(res) < k:
            if abs(arr[right] - median) >= abs(arr[left] - median):
                res.append(arr[right])
                right -= 1
            else:
                res.append(arr[left])
                left += 1
        return res

class BrowserHistory:
    def __init__(self, homepage: str):
        self.history = [homepage]
        self.cur = 0

    def visit(self, url: str) -> None:
        self.history = self.history[:self.cur + 1]
        self.history.append(url)
        self.cur += 1

    def back(self, steps: int) -> str:
        self.cur = max(0, self.cur - steps)
        return self.history[self.cur]

    def forward(self, steps: int) -> str:
        self.cur = min(len(self.history) - 1, self.cur + steps)
        return self.history[self.cur]

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(i, prev_color, neighborhoods):
            if neighborhoods > target:
                return float('inf')
            if i == m:
                return 0 if neighborhoods == target else float('inf')
            if houses[i] != 0:
                new_neigh = neighborhoods + (1 if houses[i] != prev_color else 0)
                return dp(i + 1, houses[i], new_neigh)
            res = float('inf')
            for c in range(1, n + 1):
                new_neigh = neighborhoods + (1 if c != prev_color else 0)
                res = min(res, cost[i][c-1] + dp(i + 1, c, new_neigh))
            return res
        ans = dp(0, 0, 0)
        return ans if ans != float('inf') else -1

class Solution:
    def deleteNodes(self, head: ListNode, m: int, n: int) -> ListNode:
        cur = head
        while cur:
            for _ in range(m - 1):
                if not cur:
                    return head
                cur = cur.next
            if not cur:
                break
            tmp = cur
            for _ in range(n):
                if not tmp.next:
                    break
                tmp = tmp.next
            cur.next = tmp.next
            cur = cur.next
        return head

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        stack = []
        res = prices[:]
        for i, p in enumerate(prices):
            while stack and prices[stack[-1]] >= p:
                idx = stack.pop()
                res[idx] = prices[idx] - p
            stack.append(i)
        return res

