class Solution:
    def minSumOfLengths(self, arr: List[int], target: int) -> int:
        n = len(arr)
        best = [float('inf')] * n  # best[i] = min length subarray ending at or before i
        ans = float('inf')
        left = 0
        cur_sum = 0
        for right in range(n):
            cur_sum += arr[right]
            while cur_sum > target:
                cur_sum -= arr[left]
                left += 1
            cur_len = float('inf')
            if cur_sum == target:
                cur_len = right - left + 1
                if left > 0 and best[left - 1] != float('inf'):
                    ans = min(ans, cur_len + best[left - 1])
            best[right] = min(best[right - 1] if right > 0 else float('inf'), cur_len)
        return ans if ans != float('inf') else -1

class Solution:
    def minDistance(self, houses: List[int], k: int) -> int:
        houses.sort()
        n = len(houses)
        # cost[i][j] = cost of putting one mailbox for houses[i..j]
        cost = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(i, n):
                mid = houses[(i+j)//2]
                for h in range(i, j+1):
                    cost[i][j] += abs(houses[h] - mid)
        dp = [[float('inf')]*(k+1) for _ in range(n+1)]
        dp[0][0] = 0
        for i in range(1, n+1):
            for kk in range(1, min(i, k)+1):
                for j in range(kk, i+1):
                    dp[i][kk] = min(dp[i][kk], dp[j-1][kk-1] + cost[j-1][i-1])
        return dp[n][k]

