class Solution:
    def findLeastNumOfUniqueInts(self, arr: List[int], k: int) -> int:
        from collections import Counter
        counts = sorted(Counter(arr).values())
        removed = 0
        for c in counts:
            if k >= c:
                k -= c
                removed += 1
            else:
                break
        return len(counts) - removed

class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        if m * k > len(bloomDay):
            return -1
        def canMake(days):
            bouquets = flowers = 0
            for b in bloomDay:
                if b <= days:
                    flowers += 1
                    if flowers == k:
                        bouquets += 1
                        flowers = 0
                else:
                    flowers = 0
            return bouquets >= m
        lo, hi = min(bloomDay), max(bloomDay)
        while lo < hi:
            mid = (lo + hi) // 2
            if canMake(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class TreeAncestor:
    def __init__(self, n: int, parent: List[int]):
        self.LOG = 16
        self.up = [[-1]*n for _ in range(self.LOG)]
        self.up[0] = parent[:]
        for j in range(1, self.LOG):
            for i in range(n):
                if self.up[j-1][i] != -1:
                    self.up[j][i] = self.up[j-1][self.up[j-1][i]]

    def getKthAncestor(self, node: int, k: int) -> int:
        for j in range(self.LOG):
            if k & (1 << j):
                node = self.up[j][node]
                if node == -1:
                    return -1
        return node

class Solution:
    def copyRandomBinaryTree(self, root: 'Node') -> 'NodeCopy':
        mapping = {}
        def clone(node):
            if not node:
                return None
            if node in mapping:
                return mapping[node]
            copy = NodeCopy(node.val)
            mapping[node] = copy
