        return res

class Solution:
    def avoidFlood(self, rains: List[int]) -> List[int]:
        from sortedcontainers import SortedList
        ans = [-1] * len(rains)
        full = {}  # lake -> day it was filled
        dry_days = SortedList()  # available dry days
        for i, lake in enumerate(rains):
            if lake == 0:
                dry_days.add(i)
                ans[i] = 1  # placeholder
            else:
                if lake in full:
                    # need a dry day after full[lake]
                    idx = dry_days.bisect_left(full[lake])
                    if idx == len(dry_days):
                        return []
                    day = dry_days[idx]
                    dry_days.remove(day)
                    ans[day] = lake
                full[lake] = i
        return ans

class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        for i, e in enumerate(edges):
            e.append(i)
        edges.sort(key=lambda x: x[2])

        def find(parent, x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def mst_weight(n, edges, include=-1, exclude=-1):
            parent = list(range(n))
            weight = 0
            count = 0
            if include != -1:
                e = edges[include]
                pa, pb = find(parent, e[0]), find(parent, e[1])
                parent[pa] = pb
                weight += e[2]
                count += 1
            for i, e in enumerate(edges):
                if i == exclude or i == include:
                    continue
                pa, pb = find(parent, e[0]), find(parent, e[1])
                if pa != pb:
                    parent[pa] = pb
                    weight += e[2]
                    count += 1
            return weight if count == n - 1 else float('inf')

        base = mst_weight(n, edges)
        critical, pseudo = [], []
        for i in range(len(edges)):
            if mst_weight(n, edges, exclude=i) > base:
                critical.append(edges[i][3])
            elif mst_weight(n, edges, include=i) == base:
                pseudo.append(edges[i][3])
        return [critical, pseudo]

