class Solution:
    def minNumberOfSemesters(self, n: int, relations: List[List[int]], k: int) -> int:
        prereq = [0] * n
        for u, v in relations:
            prereq[v-1] |= 1 << (u-1)
        dp = [n] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            # find all courses that can be taken
            available = 0
            for i in range(n):
                if not (mask & (1 << i)) and (prereq[i] & mask) == prereq[i]:
                    available |= 1 << i
            # enumerate subsets of available with at most k bits
            sub = available
            while sub:
                if bin(sub).count('1') <= k:
                    dp[mask | sub] = min(dp[mask | sub], dp[mask] + 1)
                sub = (sub - 1) & available
        return dp[(1 << n) - 1]

class Solution:
    def isPathCrossing(self, path: str) -> bool:
        x = y = 0
        visited = {(0, 0)}
        dirs = {'N':(0,1),'S':(0,-1),'E':(1,0),'W':(-1,0)}
        for d in path:
            dx, dy = dirs[d]
            x, y = x + dx, y + dy
            if (x, y) in visited:
                return True
            visited.add((x, y))
        return False

class Solution:
    def canArrange(self, arr: List[int], k: int) -> bool:
        from collections import Counter
        remainder = Counter(x % k for x in arr)
        for r in remainder:
            if r == 0:
                if remainder[r] % 2 != 0:
                    return False
            elif remainder[r] != remainder[k - r]:
                return False
        return True

class Solution:
    def numSubseq(self, nums: List[int], target: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)
        res = 0
        left, right = 0, n - 1
        while left <= right:
            if nums[left] + nums[right] <= target:
                res = (res + pow(2, right - left, MOD)) % MOD
                left += 1
            else:
                right -= 1
        return res

class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        from collections import deque
        dq = deque()  # stores (yi - xi, xi)
        ans = float('-inf')
        for xj, yj in points:
            while dq and xj - dq[0][1] > k:
                dq.popleft()
            if dq:
                ans = max(ans, dq[0][0] + yj + xj)
            val = yj - xj
            while dq and dq[-1][0] <= val:
                dq.pop()
            dq.append((val, xj))
        return ans

class FileSharing:
    def __init__(self, m: int):
        import heapq
        self.chunks_to_users = [set() for _ in range(m + 1)]
        self.user_chunks = {}
        self.available_ids = [1]
        self.next_id = 2
        heapq.heapify(self.available_ids)

    def join(self, ownedChunks: List[int]) -> int:
        import heapq
        if self.available_ids:
            uid = heapq.heappop(self.available_ids)
        else:
            uid = self.next_id
            self.next_id += 1
        if not self.available_ids:
            heapq.heappush(self.available_ids, self.next_id)
            self.next_id += 1
        self.user_chunks[uid] = set(ownedChunks)
        for c in ownedChunks:
            self.chunks_to_users[c].add(uid)
        return uid

    def leave(self, userID: int) -> None:
        import heapq
        for c in self.user_chunks[userID]:
            self.chunks_to_users[c].discard(userID)
        del self.user_chunks[userID]
        heapq.heappush(self.available_ids, userID)

    def request(self, userID: int, chunkID: int) -> List[int]:
        users = sorted(self.chunks_to_users[chunkID])
        if users:
            self.user_chunks[userID].add(chunkID)
            self.chunks_to_users[chunkID].add(userID)
        return users
